-- Non-SARGable: function on column blocks index usage
SELECT * FROM dbo.Orders
WHERE YEAR(OrderDate) = 2024;

-- SARGable: rewrite as range predicate
SELECT * FROM dbo.Orders
WHERE OrderDate >= '2024-01-01'
  AND OrderDate < '2025-01-01';

-- Non-SARGable: leading wildcard
SELECT * FROM dbo.Customers
WHERE CustomerName LIKE '%Smith';

-- SARGable: prefix matching (if data supports it)
SELECT * FROM dbo.Customers
WHERE CustomerName LIKE 'Smith%';

-- Anti-pattern: cursor processing (row-by-row)
DECLARE @CustomerID INT;
DECLARE cust_cursor CURSOR FOR
    SELECT CustomerID FROM dbo.Customers WHERE IsActive = 1;
OPEN cust_cursor;
FETCH NEXT FROM cust_cursor INTO @CustomerID;
WHILE @@FETCH_STATUS = 0
BEGIN
    UPDATE dbo.Orders
    SET ProcessedFlag = 1
    WHERE CustomerID = @CustomerID
      AND ProcessedFlag = 0;
    FETCH NEXT FROM cust_cursor INTO @CustomerID;
END
CLOSE cust_cursor;
DEALLOCATE cust_cursor;

-- Set-based alternative: single UPDATE statement
UPDATE o
SET ProcessedFlag = 1
FROM dbo.Orders o
INNER JOIN dbo.Customers c ON o.CustomerID = c.CustomerID
WHERE c.IsActive = 1
  AND o.ProcessedFlag = 0;
